const gatherEnvironments = new Set(["gather", "gather*"]);

// Environments in which \multicolumn may be used.
const multicolumnEnvironments = new Set([
    "array",
    "matrix",
    "pmatrix",
    "bmatrix",
    "Bmatrix",
    "vmatrix",
    "Vmatrix",
    "cases",
    "rcases",
    "aligned",
    "smallmatrix",
]);

// The number of array columns occupied by a row, taking the spans of any
// \multicolumn cells into account.
function logicalRowWidth(row: AnyParseNode[]): number {
    let width = 0;
    for (let i = 0; i < row.length; i++) {
        const cell = row[i];
        width += cell.type === "multicolumn" ? cell.span : 1;
    }
    return width;
}

// An interval on the vertical axis of an array, measured downward from the
// top of the array's rows.
type VerticalInterval = [number, number];

// Merge overlapping or touching intervals into a sorted, disjoint list.
function mergeIntervals(
    intervals: VerticalInterval[],
): VerticalInterval[] {
    const sorted = intervals.slice().sort((a, b) => a[0] - b[0]);
    const merged: VerticalInterval[] = [];
    for (let i = 0; i < sorted.length; i++) {
        const last = merged[merged.length - 1];
        if (last && sorted[i][0] <= last[1]) {
            last[1] = Math.max(last[1], sorted[i][1]);
        } else {
            merged.push([sorted[i][0], sorted[i][1]]);
        }
    }
    return merged;
}

// Return the parts of [0, totalHeight] that are not covered by `intervals`.
function subtractIntervals(
    totalHeight: number,
    intervals: VerticalInterval[],
): VerticalInterval[] {
    const segments: VerticalInterval[] = [];
    let pos = 0;
    const merged = mergeIntervals(intervals);
    for (let i = 0; i < merged.length; i++) {
        if (merged[i][0] > pos) {
            segments.push([pos, merged[i][0]]);
        }
        pos = Math.max(pos, merged[i][1]);
    }
    if (pos < totalHeight) {
        segments.push([pos, totalHeight]);
    }
    return segments;
}

