    let multicolumn: ParseNode<"multicolumn"> | null = null;
    let contentNodes = cellBody;
    if (cellBody.length > 0 && cellBody[0].type === "multicolumn") {
        multicolumn = assertNodeType(cellBody[0], "multicolumn");
        contentNodes = multicolumn.body.concat(cellBody.slice(1));
