    const rowBottom = body[r].pos + body[r].depth;
    for (let m = 0; m < multiColumnCells.length; ++m) {
        const mc = multiColumnCells[m];
        for (let b = mc.startCol + 1; b < mc.startCol + mc.span; ++b) {
            (ruleSuppressions[b] = ruleSuppressions[b] || [])
