for (c = 0, colDescrNum = 0;
     // Continue while either there are more columns or more column
     // descriptions, so trailing separators don't get lost.  Also
     // continue while a \multicolumn adds a rule at this boundary.
     c < nc || colDescrNum < colDescriptions.length || ruleAdditions[c];
     ++c, ++colDescrNum) {
    let colDescr: AlignSpec | undefined = colDescriptions[colDescrNum];

    let firstSeparator = true;
    let declaredSeparator = false;
    while (colDescr?.type === "separator") {
        // If there is more than one separator in a row, add a space
        // between them.
        if (!firstSeparator) {
            colSep = makeSpan(["arraycolsep"], []);
            colSep.style.width =
                makeEm(options.fontMetrics().doubleRuleSep);
            cols.push(colSep);
        }

        if (colDescr.separator === "|" || colDescr.separator === ":") {
            const lineType = colDescr.separator === "|" ? "solid" : "dashed";
            // Within rows in which a \multicolumn spans across this
            // boundary, the rule is suppressed; draw the remaining
            // segments only.
            const suppressions = ruleSuppressions[c];
            const segments = suppressions
                ? subtractIntervals(totalHeight, suppressions)
                : [[0, totalHeight]];
            for (let s = 0; s < segments.length; ++s) {
                if (segments[s][1] > segments[s][0]) {
                    cols.push(makeRuleSegment(
                        segments[s][0], segments[s][1], lineType));
                }
            }
            declaredSeparator = true;
        } else {
            throw new ParseError(
                "Invalid separator type: " + colDescr.separator);
        }

        colDescrNum++;
        colDescr = colDescriptions[colDescrNum];
        firstSeparator = false;
    }

    // Draw the per-row rules contributed by "|" in \multicolumn
    // alignment specs at boundaries that have no declared rule.
    const additions = ruleAdditions[c];
    if (additions && !declaredSeparator) {
        const segments = mergeIntervals(additions);
        for (let s = 0; s < segments.length; ++s) {
            if (segments[s][1] > segments[s][0]) {
                cols.push(makeRuleSegment(
                    segments[s][0], segments[s][1], "solid"));
            }
        }
    }

    if (c >= nc) {
        continue;
    }

    let sepwidth;
    if (c > 0 || group.hskipBeforeAndAfter) {
        sepwidth = colDescr?.pregap ?? arraycolsep;
        if (sepwidth !== 0) {
            colSep = makeSpan(["arraycolsep"], []);
            colSep.style.width = makeEm(sepwidth);
            cols.push(colSep);
        }
    }

    const colElems: Array<{
        type: "elem";
        elem: HtmlDomNode;
        shift: number;
        wrapperStyle?: CssStyle;
    }> = [];
    for (r = 0; r < nr; ++r) {
        const row = body[r];
        const elem = row[c];
        if (!elem) {
            continue;
        }
        const shift = row.pos - offset;
        elem.depth = row.depth;
        elem.height = row.height;
        // A \multicolumn cell is laid out in the first column it spans;
        // its alignment overrides the column's declared alignment.
        const mc = multiColumnRows[r].length > 0 &&
            multiColumnRows[r].find((cell) => cell.startCol === c);
        colElems.push(mc
            ? {type: "elem", elem, shift,
                wrapperStyle: {textAlign: alignMap[mc.colAlign].trim()}}
            : {type: "elem", elem, shift});
    }

    // A column may be left empty by \multicolumn cells spanning it.
    const colVList = colElems.length > 0
        ? makeVList({
            positionType: "individualShift",
            children: colElems,
        }, options)
        : makeSpan([], []);
    const colSpan = makeSpan(
        ["col-align-" + (colDescr?.align || "c")],
        [colVList],
    );
    cols.push(colSpan);

