require('@babel/register')({extensions: ['.js', '.ts']});
const katex = require('../katex.ts').default;

// 1. Rule suppression: internal rule of {|c|c|} should be segmented
let m = katex.renderToString(
    "\\begin{array}{|c|c|} \\multicolumn{2}{c}{x} \\\\ a & b \\end{array}");
const seps = m.match(/vertical-separator[^"]*" style="[^"]*"/g) || [];
console.log("=== {|c|c|} with \\multicolumn{2}{c}: separator spans:", seps.length);
seps.forEach((s) => console.log("   ", s));

// 1b. Same array without multicolumn (regression check: 3 full-height rules)
let m0 = katex.renderToString(
    "\\begin{array}{|c|c|} x & y \\\\ a & b \\end{array}");
const seps0 = m0.match(/vertical-separator[^"]*" style="[^"]*"/g) || [];
console.log("=== {|c|c|} without multicolumn: separator spans:", seps0.length);
seps0.forEach((s) => console.log("   ", s));

// 2. Rules added by the multicolumn spec in a rule-less array
m = katex.renderToString(
    "\\begin{array}{cc} \\multicolumn{2}{|c|}{x} \\\\ a & b \\end{array}");
const seps2 = m.match(/vertical-separator[^"]*" style="[^"]*"/g) || [];
console.log("=== {cc} with \\multicolumn{2}{|c|}: separator spans:", seps2.length);
seps2.forEach((s) => console.log("   ", s));

// 3. Alignment override in HTML (textAlign on the spanned cell wrapper)
m = katex.renderToString(
    "\\begin{array}{ll} a & b \\\\ \\multicolumn{2}{c}{xyz} \\end{array}");
console.log("=== text-align present:", /text-align:center/.test(m));

// 4. MathML attributes
m = katex.renderToString(
    "\\begin{array}{cc} a & b \\\\ \\multicolumn{2}{r}{x} \\end{array}");
const mtd = m.match(/<mtd[^>]*columnspan[^>]*>/g) || [];
console.log("=== MathML mtd with columnspan:", mtd);
console.log("=== columnalign attr:", /columnalign="right"/.test(m));

// 5. MathML in a pmatrix
m = katex.renderToString(
    "\\begin{pmatrix} a & b \\\\ \\multicolumn{2}{l}{x} \\end{pmatrix}");
console.log("=== pmatrix MathML:", m.match(/<mtd[^>]*columnspan[^>]*>/g));

// 6. multi-row span suppression merges
m = katex.renderToString(
    "\\begin{array}{c|c} \\multicolumn{2}{c}{x} \\\\ \\multicolumn{2}{c}{y} \\\\ a & b \\end{array}");
const seps3 = m.match(/vertical-separator[^"]*" style="[^"]*"/g) || [];
console.log("=== two consecutive mc rows, boundary-1 segments:", seps3.length);
seps3.forEach((s) => console.log("   ", s));

