            {type: "separator", separator: ":"},
            {type: "separator", separator: ":"},
        ]);
    });

});

describe("A multicolumn function", function() {

    // Heights of the vertical-separator spans in the rendered HTML.
    const separatorHeights = (expr: string): number[] => {
        const heights: number[] = [];
        katex.renderToString(expr).replace(
            /vertical-separator" style="height:([\d.]+)em/g,
            (match: string, height: string) => {
                heights.push(parseFloat(height));
                return match;
            });
        return heights;
    };

    it("should parse the span, alignment, and rule specifiers", function() {
        const parse = getParsed`\begin{array}{ccc} a & \multicolumn{2}{|c|}{x} \\ b & c & d\end{array}`;
        const cell = parse[0].body[0][1];
        expect(cell.type).toBe("multicolumn");
        expect(cell.span).toBe(2);
        expect(cell.colAlign).toBe("c");
        expect(cell.leftRule).toBe(true);
        expect(cell.rightRule).toBe(true);
        expect(cell.body[0].type).toBe("styling");
    });

    it("should build in each supported environment", function() {
        expect`\begin{array}{cc} a & b \\ \multicolumn{2}{c}{x} \end{array}`.toBuild();
        expect`\begin{matrix} a & b \\ \multicolumn{2}{c}{x} \end{matrix}`.toBuild();
        expect`\begin{pmatrix} a & b \\ \multicolumn{2}{c}{x} \end{pmatrix}`.toBuild();
        expect`\begin{bmatrix} a & b \\ \multicolumn{2}{c}{x} \end{bmatrix}`.toBuild();
        expect`\begin{Bmatrix} a & b \\ \multicolumn{2}{c}{x} \end{Bmatrix}`.toBuild();
        expect`\begin{vmatrix} a & b \\ \multicolumn{2}{c}{x} \end{vmatrix}`.toBuild();
        expect`\begin{Vmatrix} a & b \\ \multicolumn{2}{c}{x} \end{Vmatrix}`.toBuild();
        expect`\begin{cases} a & b \\ \multicolumn{2}{c}{x} \end{cases}`.toBuild();
        expect`\begin{rcases} a & b \\ \multicolumn{2}{c}{x} \end{rcases}`.toBuild();
        expect`\begin{aligned} a &= b \\ \multicolumn{2}{c}{x} \end{aligned}`.toBuild();
        expect`\begin{smallmatrix} a & b \\ \multicolumn{2}{c}{x} \end{smallmatrix}`.toBuild();
    });

    it("should accept rule specifiers and multi-digit spans", function() {
        expect`\begin{array}{cc} \multicolumn{2}{|c}{x} \\ a & b \end{array}`.toBuild();
        expect`\begin{array}{cc} \multicolumn{2}{c|}{x} \\ a & b \end{array}`.toBuild();
        expect`\begin{array}{cc} \multicolumn{2}{||c||}{x} \\ a & b \end{array}`.toBuild();
        expect`\begin{array}{cccccccccccc} \multicolumn{12}{c}{x} \end{array}`.toBuild();
    });

    it("should build when a multicolumn leaves a column empty", function() {
        expect`\begin{array}{cc} \multicolumn{2}{c}{x} \end{array}`.toBuild();
    });

    it("should count spanned columns when sizing a matrix", function() {
        const parse = getParsed`\begin{pmatrix} a & b \\ \multicolumn{3}{c}{x} & y \end{pmatrix}`;
        expect(parse[0].body[0].cols).toHaveLength(4);
    });

    it("should override the column's declared alignment", function() {
        const markup = katex.renderToString(
            r`\begin{array}{ll} a & b \\ \multicolumn{2}{c}{x} \end{array}`);
        expect(markup).toContain("text-align:center");
    });

    it("should suppress internal vertical rules within the spanned region", function() {
        const heights = separatorHeights(
            r`\begin{array}{|c|c|} \multicolumn{2}{c}{x} \\ a & b \end{array}`);
        expect(heights).toHaveLength(3);
        const fullHeight = Math.max(...heights);
        // The two edge rules keep their full height; the internal rule
        // is reduced to the rows outside the spanned region.
        expect(heights.filter((h) => h === fullHeight)).toHaveLength(2);
        expect(heights.filter((h) => h < fullHeight)).toHaveLength(1);
    });

    it("should remove a fully spanned internal vertical rule", function() {
        const heights = separatorHeights(
            r`\begin{array}{|c|c|} \multicolumn{2}{c}{x} \end{array}`);
        expect(heights).toHaveLength(2);
    });

    it("should draw vertical rules requested by the multicolumn alignment", function() {
        const heights = separatorHeights(
            r`\begin{array}{cc} \multicolumn{2}{|c|}{x} \\ a & b \end{array}`);
        expect(heights).toHaveLength(2);
    });

    it("should not affect vertical rules of arrays without \\multicolumn", function() {
        const heights = separatorHeights(
            r`\begin{array}{|c|c|} x & y \\ a & b \end{array}`);
        expect(heights).toHaveLength(3);
        expect(new Set(heights).size).toBe(1);
    });

    it("should error outside array-like environments", function() {
        expect`\multicolumn{2}{c}{x}`.not.toParse();
        expect`x + \multicolumn{1}{c}{y}`.not.toParse();
    });

    it("should error in unsupported environments", function() {
        expect`\begin{gathered} \multicolumn{1}{c}{x} \end{gathered}`.not.toParse();
        expect`\begin{matrix*}[r] \multicolumn{1}{c}{x} \end{matrix*}`.not.toParse();
        expect`\begin{dcases} \multicolumn{1}{c}{x} \end{dcases}`.not.toParse();
        expect`\begin{subarray}{c} \multicolumn{1}{c}{x} \end{subarray}`.not.toParse();
        expect`\begin{array}{c} \begin{gathered} \multicolumn{1}{c}{x} \end{gathered} \end{array}`
            .not.toParse();
    });

    it("should error on a non-integer or non-positive column count", function() {
        expect`\begin{array}{cc} \multicolumn{0}{c}{x} \end{array}`.not.toParse();
        expect`\begin{array}{cc} \multicolumn{-1}{c}{x} \end{array}`.not.toParse();
        expect`\begin{array}{cc} \multicolumn{1.5}{c}{x} \end{array}`.not.toParse();
        expect`\begin{array}{cc} \multicolumn{x}{c}{x} \end{array}`.not.toParse();
        expect`\begin{array}{cc} \multicolumn{}{c}{x} \end{array}`.not.toParse();
    });

    it("should error when the span exceeds the remaining columns in the row", function() {
        expect`\begin{array}{cc} \multicolumn{3}{c}{x} \end{array}`.not.toParse();
        expect`\begin{array}{ccc} a & \multicolumn{3}{c}{x} \end{array}`.not.toParse();
        expect`\begin{array}{ccc} a & b & \multicolumn{2}{c}{x} \end{array}`.not.toParse();
        expect`\begin{cases} \multicolumn{3}{c}{x} \end{cases}`.not.toParse();
    });

    it("should error on an invalid alignment", function() {
        expect`\begin{array}{cc} \multicolumn{2}{}{x} \end{array}`.not.toParse();
        expect`\begin{array}{cc} \multicolumn{2}{d}{x} \end{array}`.not.toParse();
        expect`\begin{array}{cc} \multicolumn{2}{lc}{x} \end{array}`.not.toParse();
        expect`\begin{array}{cc} \multicolumn{2}{|}{x} \end{array}`.not.toParse();
        expect`\begin{array}{cc} \multicolumn{2}{l|c}{x} \end{array}`.not.toParse();
    });

    it("should error when not at the beginning of a cell", function() {
        expect`\begin{array}{cc} a \multicolumn{1}{c}{x} \end{array}`.not.toParse();
        expect`\begin{array}{cc} \multicolumn{1}{c}{x} \multicolumn{1}{c}{y} \end{array}`
            .not.toParse();
    });

});

