/* eslint-disable no-console */
require('@babel/register')({extensions: ['.js', '.ts']});
const katex = require('../katex.ts').default;

// Inspect DOM structure: which column vlist holds the spanned cell?
const tree = katex.__renderToDomTree(
    "\\begin{array}{ccc} a & \\multicolumn{2}{c}{xyz} \\\\ b & c & d \\end{array}",
    {});
const htmlNode = tree.children[1]; // .katex-html
function findMtable(node) {
    if (node.classes && node.classes.includes("mtable")) {
        return node;
    }
    for (const ch of node.children || []) {
        const found = findMtable(ch);
        if (found) {
            return found;
        }
    }
    return null;
}
const mtable = findMtable(htmlNode);
console.log("mtable children classes:");
mtable.children.forEach((ch, i) => {
    const ta = ch.style && ch.style.textAlign;
    console.log(`  [${i}] ${ch.classes.join(" ")}${ta ? " textAlign=" + ta : ""}`);
});
// column spans (col-align-*) and their vlist row count + any text-align wrappers
const colSpans = mtable.children.filter((ch) =>
    ch.classes.some((cl) => cl.startsWith("col-align")));
console.log("columns:", colSpans.length);
colSpans.forEach((col, i) => {
    const vlist = col.children[0];
    const rows = [];
    const collect = (n) => {
        if (n.style && n.style.textAlign) {
            rows.push("textAlign=" + n.style.textAlign);
        }
        (n.children || []).forEach(collect);
    };
    collect(vlist);
    console.log(`  col ${i} (${col.classes.join(" ")}): alignment wrappers: ${rows.join(", ") || "none"}`);
});

// macro-defined multicolumn
try {
    katex.renderToString(
        "\\def\\mc{\\multicolumn{2}{c}{x}}\\begin{array}{cc} \\mc \\\\ a & b \\end{array}");
    console.log("OK    macro-defined \\multicolumn");
} catch (e) {
    console.log("FAIL  macro-defined:", e.message);
}

// displayMode
try {
    katex.renderToString(
        "\\begin{array}{cc} a & b \\\\ \\multicolumn{2}{c}{x} \\end{array}",
        {displayMode: true});
    console.log("OK    displayMode");
} catch (e) {
    console.log("FAIL  displayMode:", e.message);
}

// strict mode should still work
try {
    katex.renderToString(
        "\\begin{array}{cc} a & b \\\\ \\multicolumn{2}{c}{x} \\end{array}",
        {strict: true});
    console.log("OK    strict mode");
} catch (e) {
    console.log("FAIL  strict mode:", e.message);
}

