// \multicolumn{n}{alignment}{content} makes `content` span `n` columns of
// the current row, aligned according to `alignment`, which must contain
// exactly one of "l", "c", or "r" plus optional "|" vertical rule
// specifiers.  Valid only inside array-like environments; parseArray
// records which environments allow it via the scoped "\\multicolumn@" flag.
defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
    },
    handler({parser, token}, args) {
        if (parser.gullet.macros.get("\\multicolumn@") !== "1") {
            throw new ParseError(
                "\\multicolumn valid only within array-like environments",
                token);
        }

        // Read the characters of an argument consisting of symbol nodes.
        const argText = function(arg: AnyParseNode): string {
            const nodes = checkSymbolNodeType(arg)
                ? [arg]
                : assertNodeType(arg, "ordgroup").body;
            let text = "";
            for (let i = 0; i < nodes.length; i++) {
                const node = checkSymbolNodeType(nodes[i]);
                if (!node) {
                    throw new ParseError(
                        "Unexpected node in \\multicolumn argument", token);
                }
                text += node.text;
            }
            return text;
        };

        // The column count must be a positive integer.
        const countText = argText(args[0]);
        const span = /^[0-9]+$/.test(countText) ?
            parseInt(countText, 10) : NaN;
        if (!(span >= 1)) {
            throw new ParseError(
                "\\multicolumn column count must be a positive integer, " +
                `got "${countText}"`, token);
        }

        // The alignment must be exactly one of "l", "c", or "r", with
        // optional "|" vertical rule specifiers.
        const alignText = argText(args[1]);
        const alignMatch = /^(\|*)([lcr])(\|*)$/.exec(alignText);
        if (!alignMatch) {
            throw new ParseError(
                "\\multicolumn alignment must contain exactly one of " +
                `"l", "c", or "r" and optional "|", got "${alignText}"`,
                token);
        }

        return {
            type: "multicolumn",
            mode: parser.mode,
            span,
            colAlign: alignMatch[2],
            leftRule: alignMatch[1].length > 0,
            rightRule: alignMatch[3].length > 0,
            body: [args[2]],
        };
    },

    // Spanning, alignment, and vertical rule adjustments are handled by the
    // array builders; these builders render only the cell content.
    htmlBuilder(group, options) {
        return html.buildGroup(group.body[0], options);
    },

    mathmlBuilder(group, options) {
        return mml.buildGroup(group.body[0], options);
    },
});
